"""Unit tests for openGym catalogue parsing, custom exercise merging, and search."""

import pytest

from health_coach.opengym.catalogue import (
    canonical_id,
    merge_custom_exercises,
    parse_aliases_js,
    parse_catalogue_js,
    search_catalogue,
)

SAMPLE_CATALOGUE_JS = """
// generated by scripts/catalogue/build.mjs
export const EXDB=[
  {
    "id":"bench-press","n":"Bench Press","bp":"chest","eq":"barbell",
    "tg":"pectorals","mg":"chest","sm":["triceps","shoulders"],"cat":"strength"
  },
  {
    "id":"pull-up","n":"Pull-up","bp":"back","eq":"body weight",
    "tg":"lats","mg":"back","sm":["biceps","forearms"],"cat":"calisthenics"
  },
  {
    "id":"squat","n":"Barbell Squat","bp":"upper legs","eq":"barbell",
    "tg":"quads","mg":"quadriceps","sm":["glutes","hamstrings"],"cat":"strength"
  }
];
"""


def test_parse_catalogue_js() -> None:
    data = parse_catalogue_js(SAMPLE_CATALOGUE_JS)
    assert len(data) == 3
    assert data[0]["id"] == "bench-press"
    assert data[0]["n"] == "Bench Press"
    assert data[0]["sm"] == ["triceps", "shoulders"]


def test_parse_catalogue_js_invalid() -> None:
    with pytest.raises(ValueError, match="EXDB"):
        parse_catalogue_js("const FOO = 123;")


def test_parse_catalogue_with_alias_export() -> None:
    # The real file (v1.4.1) has a second export after EXDB; brackets inside it must not
    # confuse the parser.
    js = (
        'export const EXDB=[{"id":"0025","n":"barbell bench press"}];\n'
        'export const EXALIAS={"1019":"3841","3841":"0025","x":"[odd]"};\n'
    )
    assert parse_catalogue_js(js) == [{"id": "0025", "n": "barbell bench press"}]
    aliases = parse_aliases_js(js)
    assert canonical_id("1019", aliases) == "0025"
    assert canonical_id("0025", aliases) == "0025"
    assert parse_aliases_js("export const EXDB=[];") == {}


def test_canonical_id_stops_on_cycles() -> None:
    assert canonical_id("a", {"a": "b", "b": "a"}) in {"a", "b"}


def test_merge_custom_exercises() -> None:
    catalogue = [
        {"id": "bench-press", "n": "Bench Press"},
        {"id": "squat", "n": "Squat"},
    ]
    customs = [
        {"id": "c1", "n": "Custom Row", "custom": True},
        {"id": "bench-press", "n": "My Bench Override", "custom": True},
    ]
    merged = merge_custom_exercises(catalogue, customs)
    # Customs come first, and shadowing customs override catalogue
    assert len(merged) == 3
    assert merged[0]["id"] == "c1"
    assert merged[1]["id"] == "bench-press"
    assert merged[1]["n"] == "My Bench Override"
    assert merged[2]["id"] == "squat"


def test_search_catalogue() -> None:
    catalogue = [
        {
            "id": "1",
            "n": "Barbell Bench Press",
            "bp": "chest",
            "eq": "barbell",
            "tg": "pectorals",
            "mg": "chest",
            "sm": ["triceps"],
        },
        {
            "id": "2",
            "n": "Dumbbell Incline Press",
            "bp": "chest",
            "eq": "dumbbell",
            "tg": "upper chest",
            "mg": "chest",
            "sm": ["triceps", "shoulders"],
        },
        {
            "id": "3",
            "n": "Pull Up",
            "bp": "back",
            "eq": "body weight",
            "tg": "lats",
            "mg": "back",
            "sm": ["biceps"],
        },
    ]

    # Search by name query
    res = search_catalogue(catalogue, query="incline")
    assert len(res) == 1
    assert res[0]["id"] == "2"

    # Search by equipment
    res = search_catalogue(catalogue, equipment="barbell")
    assert len(res) == 1
    assert res[0]["id"] == "1"

    # Search by muscle (in secondary muscles)
    res = search_catalogue(catalogue, muscle="biceps")
    assert len(res) == 1
    assert res[0]["id"] == "3"

    # Search by muscle and query
    res = search_catalogue(catalogue, query="press", muscle="triceps")
    assert len(res) == 2
